from ielts_h import rstory
READ3 = [rstory("The Night Market", "Skimming dan scanning",
 "Every Friday evening, the old harbour area turns into a night market. It opened in 2012 with only twelve stalls, but today there are more than a hundred. Most stalls sell food, such as grilled fish and sweet pancakes, while others offer clothes and handmade souvenirs. The market opens at six and closes at midnight. Prices are low, so many students go there after class. The city council plans to move the market to a larger square next year because the harbour is now too crowded.",
 "Setiap Jumat malam, kawasan pelabuhan tua berubah menjadi pasar malam. Pasar ini dibuka tahun 2012 dengan hanya dua belas kios, tetapi kini ada lebih dari seratus. Sebagian besar kios menjual makanan, seperti ikan bakar dan panekuk manis, sedangkan yang lain menawarkan pakaian dan suvenir buatan tangan. Pasar buka pukul enam dan tutup tengah malam. Harganya murah, sehingga banyak pelajar pergi ke sana setelah sekolah. Dewan kota berencana memindahkan pasar ke alun-alun yang lebih besar tahun depan karena pelabuhan kini terlalu ramai.",
 [("Skimming: apa gagasan utama teks?", "sebuah pasar malam yang berkembang dan akan dipindah", "cara memancing ikan di pelabuhan", "sejarah kota pelabuhan tua", "peraturan baru untuk pelajar", "Kalimat pertama dan terakhir merangkum isi."),
  ("Scanning: berapa kios saat pasar dibuka?", "dua belas", "seratus", "dua puluh", "dua ratus", "Teks: twelve stalls."),
  ("Scanning: pukul berapa pasar tutup?", "tengah malam", "pukul enam", "pukul sembilan", "pukul sebelas", "Teks: closes at midnight.")],
 [("The market opens every day of the week.", 'F', "Teks: every Friday evening."),
  ("Most stalls sell food.", 'T', "Teks: Most stalls sell food."),
  ("The market will move because the harbour is crowded.", 'T', "Teks: too crowded.")],
 [("Pasar ini punya lebih dari seratus kios.", "There are more than a ___ stalls.", "hundred", "A hundred = seratus."),
  ("Harga di pasar itu murah.", "Prices are ___.", "low", "Teks: Prices are low.")])]
